#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    long long k; scanf("%lld", &k);
    int l = 0, r = n - 1;
    for (int i = 0; i < n - 1; i++) if (a[i] > a[i + 1]) { r = i; l = i + 1; break; }
    int found = 0;
    while (l != r) {
        if (a[l] + a[r] == k) { found = 1; break; }
        if (a[l] + a[r] < k) l = (l + 1) % n;
        else r = (n + r - 1) % n;
    }
    printf("%s\n", found ? "Yes" : "No");
    return 0;
}

code.C++:
#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;
int main() {
    int n; if (!(cin >> n)) return 0;
    vector<long long> a(n);
    unordered_set<long long> st;
    for (int i = 0; i < n; i++) { cin >> a[i]; st.insert(a[i]); }
    long long k; cin >> k;
    bool found = false;
    for (long long x : a) if (st.count(k - x) && k - x != x) { found = true; break; }
    cout << (found ? "Yes" : "No") << "\n";
    return 0;
}

