import java.util.Scanner;
import java.util.HashSet;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long[] a = new long[n];
            HashSet<Long> st = new HashSet<>();
            for (int i = 0; i < n; i++) { a[i] = sc.nextLong(); st.add(a[i]); }
            long k = sc.nextLong();
            boolean found = false;
            for (long x : a) if (st.contains(k - x) && k - x != x) { found = true; break; }
            System.out.println(found ? "Yes" : "No");
        }
    }
}

