const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    const arr = toks.slice(1, n + 1).map(x => BigInt(x));
    const k = BigInt(toks[n + 1]);
    const st = new Set(arr);
    let found = false;
    for (const x of arr) if (st.has(k - x) && k - x !== x) { found = true; break; }
    console.log(found ? "Yes" : "No");
}
main();

